    58  /* Check if the requested parent node exists, has the right node class and is
    59   * referenced with an allowed (hierarchical) reference type. For "type" nodes,
    60   * only hasSubType references are allowed. */
    61  static UA_StatusCode
    62  checkParentReference(UA_Server *server, UA_Session *session, UA_NodeClass nodeClass,
    63                       const UA_NodeId *parentNodeId, const UA_NodeId *referenceTypeId) {
    64      /* Objects do not need a parent (e.g. mandatory/optional modellingrules) */
    65      if(nodeClass == UA_NODECLASS_OBJECT && UA_NodeId_isNull(parentNodeId) &&
    66         UA_NodeId_isNull(referenceTypeId))
    67          return UA_STATUSCODE_GOOD;
    68
    69      /* Omit checks during bootstrap */
    70      if(server->bootstrapNS0)
    71          return UA_STATUSCODE_GOOD;
    72
    73      /* See if the parent exists */
    74      const UA_Node *parent = UA_Nodestore_get(server, parentNodeId);
    75      if(!parent) {
    76          UA_LOG_INFO_SESSION(server->config.logger, session,
    77                              "AddNodes: Parent node not found");
    78          return UA_STATUSCODE_BADPARENTNODEIDINVALID;
    79      }
    80
    81      UA_NodeClass parentNodeClass = parent->nodeClass;
    82      UA_Nodestore_release(server, parent);
    83
    84      /* Check the referencetype exists */
    85      const UA_ReferenceTypeNode *referenceType = (const UA_ReferenceTypeNode*)
    86          UA_Nodestore_get(server, referenceTypeId);
    87      if(!referenceType) {
    88          UA_LOG_INFO_SESSION(server->config.logger, session,
    89                              "AddNodes: Reference type to the parent not found");
    90          return UA_STATUSCODE_BADREFERENCETYPEIDINVALID;
    91      }
    92
    93      /* Check if the referencetype is a reference type node */
    94      if(referenceType->nodeClass != UA_NODECLASS_REFERENCETYPE) {
    95          UA_LOG_INFO_SESSION(server->config.logger, session,
    96                              "AddNodes: Reference type to the parent invalid");
    97          UA_Nodestore_release(server, (const UA_Node*)referenceType);
    98          return UA_STATUSCODE_BADREFERENCETYPEIDINVALID;
    99      }
   100
   101      UA_Boolean referenceTypeIsAbstract = referenceType->isAbstract;
   102      UA_Nodestore_release(server, (const UA_Node*)referenceType);
   103      /* Check that the reference type is not abstract */
   104      if(referenceTypeIsAbstract == true) {
   105          UA_LOG_INFO_SESSION(server->config.logger, session,
   106                              "AddNodes: Abstract reference type to the parent not allowed");
   107          return UA_STATUSCODE_BADREFERENCENOTALLOWED;
   108      }
   109
   110      /* Check hassubtype relation for type nodes */
   111      if(nodeClass == UA_NODECLASS_DATATYPE ||
   112         nodeClass == UA_NODECLASS_VARIABLETYPE ||
   113         nodeClass == UA_NODECLASS_OBJECTTYPE ||
   114         nodeClass == UA_NODECLASS_REFERENCETYPE) {
   115          /* type needs hassubtype reference to the supertype */
   116          if(!UA_NodeId_equal(referenceTypeId, &subtypeId)) {
   117              UA_LOG_INFO_SESSION(server->config.logger, session,
   118                                  "AddNodes: New type node need to have a "
   119                                  "HasSubType reference");
   120              return UA_STATUSCODE_BADREFERENCENOTALLOWED;
   121          }
   122          /* supertype needs to be of the same node type  */
   123          if(parentNodeClass != nodeClass) {
   124              UA_LOG_INFO_SESSION(server->config.logger, session,
   125                                  "AddNodes: New type node needs to be of the same "
   126                                  "node type as the parent");
   127              return UA_STATUSCODE_BADPARENTNODEIDINVALID;
   128          }
   129          return UA_STATUSCODE_GOOD;
   130      }
   131
   132      /* Test if the referencetype is hierarchical */
   133      const UA_NodeId hierarchicalReference =
   134          UA_NODEID_NUMERIC(0, UA_NS0ID_HIERARCHICALREFERENCES);
   135      if(!isNodeInTree(&server->config.nodestore, referenceTypeId,
   136                       &hierarchicalReference, &subtypeId, 1)) {
   137          UA_LOG_INFO_SESSION(server->config.logger, session,
   138                              "AddNodes: Reference type is not hierarchical");
   139          return UA_STATUSCODE_BADREFERENCETYPEIDINVALID;
   140      }
   141
   142      return UA_STATUSCODE_GOOD;
   143  }
