   145  static UA_StatusCode
   146  typeCheckVariableNode(UA_Server *server, UA_Session *session,
   147                        const UA_VariableNode *node,
   148                        const UA_VariableTypeNode *vt,
   149                        const UA_NodeId *parentNodeId) {
   150      /* The value might come from a datasource, so we perform a
   151       * regular read. */
   152      UA_DataValue value;
   153      UA_DataValue_init(&value);
   154      UA_StatusCode retval = readValueAttribute(server, session, node, &value);
   155      if(retval != UA_STATUSCODE_GOOD)
   156          return retval;
   157
   158      /* Check the datatype against the vt */
   159      if(!compatibleDataType(server, &node->dataType, &vt->dataType, false))
   160          return UA_STATUSCODE_BADTYPEMISMATCH;
   161
   162      /* Get the array dimensions */
   163      size_t arrayDims = node->arrayDimensionsSize;
   164      if(arrayDims == 0 && value.hasValue && value.value.type &&
   165         !UA_Variant_isScalar(&value.value)) {
   166          arrayDims = 1; /* No array dimensions on an array implies one dimension */
   167      }
   168
   169      /* Check valueRank against array dimensions */
   170      if(!(node->nodeClass == UA_NODECLASS_VARIABLETYPE &&
   171           ((const UA_VariableTypeNode*)node)->isAbstract && node->valueRank == 0) &&
   172          !compatibleValueRankArrayDimensions(node->valueRank, arrayDims))
   173          return UA_STATUSCODE_BADTYPEMISMATCH;
   174
   175      /* If variable node is created below BaseObjectType and has its default valueRank of -2,
   176       * skip the test */
   177      const UA_NodeId objectTypes = UA_NODEID_NUMERIC(0, UA_NS0ID_BASEOBJECTTYPE);
   178      UA_NodeId refs[2];
   179      refs[0] = UA_NODEID_NUMERIC(0, UA_NS0ID_HASSUBTYPE);
   180      refs[1] = UA_NODEID_NUMERIC(0, UA_NS0ID_HASCOMPONENT);
