   621  static UA_StatusCode
   622  addTypeDefRef(UA_Server *server, UA_Session *session,
   623                const UA_Node *node, const UA_Node *type) {
   624      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   625      UA_AddReferencesItem addref;
   626      UA_AddReferencesItem_init(&addref);
   627      addref.sourceNodeId = node->nodeId;
   628      addref.referenceTypeId = UA_NODEID_NUMERIC(0, UA_NS0ID_HASTYPEDEFINITION);
   629      addref.isForward = true;
   630      addref.targetNodeId.nodeId = type->nodeId;
   631      Operation_addReference(server, session, NULL, &addref, &retval);
   632      return retval;
   633  }
