   635  static UA_StatusCode
   636  getTypeDef(UA_Server *server, const UA_Node *node, UA_NodeId **typeDefinitionId) {
   637      UA_NodeId hasTypeDef = UA_NODEID_NUMERIC(0, UA_NS0ID_HASTYPEDEFINITION);
   638      for (size_t i=0; i< node->referencesSize; i++) {
   639          if (node->references[i].isInverse == UA_FALSE && UA_NodeId_equal(&node->references[i].referenceTypeId, &hasTypeDef) &&
   640              node->references[i].targetIdsSize > 0) {
   641              *typeDefinitionId = &node->references[i].targetIds[0].nodeId;
   642              return UA_STATUSCODE_GOOD;
   643          }
   644      }
   645
   646      return UA_STATUSCODE_BADNOTFOUND;
   647  }
