   649  static UA_StatusCode
   650  addParentRef(UA_Server *server, UA_Session *session,
   651               const UA_NodeId *nodeId,
   652               const UA_NodeId *referenceTypeId,
   653               const UA_NodeId *parentNodeId) {
   654      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   655      UA_AddReferencesItem ref_item;
   656      UA_AddReferencesItem_init(&ref_item);
   657      ref_item.sourceNodeId = *nodeId;
   658      ref_item.referenceTypeId = *referenceTypeId;
   659      ref_item.isForward = false;
   660      ref_item.targetNodeId.nodeId = *parentNodeId;
   661      Operation_addReference(server, session, NULL, &ref_item, &retval);
   662      return retval;
   663  }
