   676  static UA_StatusCode
   677  addParentAndTypeRef(UA_Server *server, UA_Session *session, const UA_Node *node, const UA_NodeId *parentNodeId,
   678                      const UA_NodeId *referenceTypeId, const UA_NodeId *typeDefinitionId) {
   679
   680      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   681      const UA_Node *type = NULL;
   682
   683      /* Use the typeDefinition as parent for type-nodes */
   684      if(node->nodeClass == UA_NODECLASS_VARIABLETYPE ||
   685         node->nodeClass == UA_NODECLASS_OBJECTTYPE ||
   686         node->nodeClass == UA_NODECLASS_REFERENCETYPE ||
   687         node->nodeClass == UA_NODECLASS_DATATYPE) {
   688          if(UA_NodeId_equal(referenceTypeId, &UA_NODEID_NULL))
   689              referenceTypeId = &hasSubtype;
   690          const UA_Node *parentNode = UA_Nodestore_get(server, parentNodeId);
   691          if(parentNode) {
   692              if(parentNode->nodeClass == node->nodeClass)
   693                  typeDefinitionId = parentNodeId;
   694              UA_Nodestore_release(server, parentNode);
   695          }
   696      }
   697
   698      if(server->bootstrapNS0)
   699          goto get_type;
   700
   701      /* Check parent reference. Objects may have no parent. */
   702      retval = checkParentReference(server, session, node->nodeClass,
   703                                    parentNodeId, referenceTypeId);
   704      if(retval != UA_STATUSCODE_GOOD) {
   705          UA_LOG_INFO_SESSION(server->config.logger, session,
   706                              "AddNodes: The parent reference is invalid");
