   711      /* Replace empty typeDefinition with the most permissive default */
   712      if((node->nodeClass == UA_NODECLASS_VARIABLE ||
   713          node->nodeClass == UA_NODECLASS_OBJECT) &&
   714         UA_NodeId_isNull(typeDefinitionId)) {
   715          UA_LOG_INFO_SESSION(server->config.logger, session,
   716                              "AddNodes: No TypeDefinition; Use the default "
   717                                  "TypeDefinition for the Variable/Object");
