  1026  static void
  1027  Operation_addNode(UA_Server *server, UA_Session *session, void *nodeContext,
  1028                    const UA_AddNodesItem *item, UA_AddNodesResult *result) {
  1029      result->statusCode = Operation_addNode_begin(server, session, nodeContext,
  1030                                                   item, &item->parentNodeId.nodeId, &item->referenceTypeId, &result->addedNodeId);
  1031      if(result->statusCode != UA_STATUSCODE_GOOD)
  1032          return;
  1033
  1034      /* AddNodes_finish */
  1035      result->statusCode =
  1036          Operation_addNode_finish(server, session, &result->addedNodeId);
  1037
  1038      /* If finishing failed, the node was deleted */
  1039      if(result->statusCode != UA_STATUSCODE_GOOD)
  1040          UA_NodeId_deleteMembers(&result->addedNodeId);
  1041  }
